-- === primitives ==========================================================

local byte, sub, char = string.byte, string.sub, string.char

function M.u8(s, i)
    return byte(s, i) or 0
end

function M.u16(s, i)
    local lo, hi = byte(s, i), byte(s, i + 1)
    if not lo or not hi then return 0 end
    return lo + hi * 256
end

function M.putU8(v)
    return char(v % 256)
end

function M.putU16(v)
    v = v % 65536
    -- (v - v % 256) / 256 is an exact integer divide with no `math` and no
    -- floating-point residue: the numerator is already a multiple of 256.
    return char(v % 256, ((v - v % 256) / 256) % 256)
end

-- Fixed-width NUL-padded field. Truncation is deliberate: the record layout is
-- fixed, so a longer name would shift every byte after it.
function M.putName(name, len)
    len = len or M.NAME_LEN
    name = sub(name or "", 1, len)
    local pad = len - #name
    if pad > 0 then name = name .. string.rep("\0", pad) end
    return name
end

function M.getName(s, i, len)
    len = len or M.NAME_LEN
    local raw = sub(s, i, i + len - 1)
    local z = raw:find("\0", 1, true)
    if z then raw = sub(raw, 1, z - 1) end
    return raw
end

-- Test a flags bitfield with neither `math` (absent on the console) nor bit32
-- (present, but this needs nothing from it).
function M.hasFlag(flags, mask)
    return ((flags - flags % mask) / mask) % 2 == 1
end

-- === client -> server encoders ===========================================

function M.setName(name)      return M.putU8(M.C2S.SET_NAME) .. M.putName(name) end
function M.listRooms(page)    return M.putU8(M.C2S.LIST_ROOMS) .. M.putU8(page or 0) end
function M.createRoom(name, private, mapId)
    return M.putU8(M.C2S.CREATE_ROOM) .. M.putName(name) .. M.putU8(private and 1 or 0)
        .. M.putU8(mapId or 0)
end
function M.joinRoom(roomId)   return M.putU8(M.C2S.JOIN_ROOM) .. M.putU16(roomId) end
function M.joinByCode(code)   return M.putU8(M.C2S.JOIN_BY_CODE) .. M.putName(code, M.CODE_LEN) end
function M.leaveRoom()        return M.putU8(M.C2S.LEAVE_ROOM) end
function M.startGame()        return M.putU8(M.C2S.START_GAME) end
function M.taskComplete(id)   return M.putU8(M.C2S.TASK_COMPLETE) .. M.putU8(id) end
function M.reportBody(slot)   return M.putU8(M.C2S.REPORT_BODY) .. M.putU8(slot) end
function M.vote(slot)         return M.putU8(M.C2S.VOTE) .. M.putU8(slot) end
function M.kill(slot)         return M.putU8(M.C2S.KILL) .. M.putU8(slot) end
function M.sabotage(kind)     return M.putU8(M.C2S.SABOTAGE) .. M.putU8(kind) end
function M.fixSabotage(kind)  return M.putU8(M.C2S.FIX_SABOTAGE) .. M.putU8(kind) end
function M.useVent(id)        return M.putU8(M.C2S.USE_VENT) .. M.putU8(id) end
function M.callMeeting()      return M.putU8(M.C2S.CALL_MEETING) end
function M.ventState(entered) return M.putU8(M.C2S.VENT_STATE) .. M.putU8(entered and 1 or 0) end
function M.requestState()     return M.putU8(M.C2S.REQUEST_STATE) end
function M.returnToLobby()    return M.putU8(M.C2S.RETURN_TO_LOBBY) end
function M.setMap(mapId)      return M.putU8(M.C2S.SET_MAP) .. M.putU8((mapId or 0) % M.MAP_COUNT) end

-- === server -> client decoders ===========================================

-- Returns subtype, body (1-indexed string). nil on an empty payload.
function M.decode(payload)
    if not payload or #payload < 1 then return nil, nil end
    return byte(payload, 1), sub(payload, 2)
end

-- body of ROOM_LIST -> page, pageCount, { {id, playerCount, flags, name}, ... }
function M.parseRoomList(body)
    local page, pageCount, count = M.u8(body, 1), M.u8(body, 2), M.u8(body, 3)
    local rooms = {}
    for i = 1, count do
        local o = 4 + (i - 1) * M.ROOM_RECORD
        if o + M.ROOM_RECORD - 1 > #body then break end  -- truncated: stop, never error
        rooms[i] = {
            id          = M.u16(body, o),
            playerCount = M.u8(body, o + 2),
            flags       = M.u8(body, o + 3),
            name        = M.getName(body, o + 4),
        }
        rooms[i].private    = M.hasFlag(rooms[i].flags, M.ROOM_FLAG_PRIVATE)
        rooms[i].inProgress = M.hasFlag(rooms[i].flags, M.ROOM_FLAG_IN_PROGRESS)
        -- No `math` and no bit32 needed: an exact integer shift-right-2 built
        -- from the remainder, the same way putU16 divides.
        local f = rooms[i].flags
        rooms[i].mapId = ((f - f % M.ROOM_MAP_SHIFT) / M.ROOM_MAP_SHIFT) % (M.ROOM_MAP_MASK + 1)
    end
    return page, pageCount, rooms
end

-- body of GAME_STARTING -> mapId
--
-- Byte 1 is the countdown, which this message has always carried; the map is
-- byte 2. An older server sends only the countdown, and u8 answers 0 for a byte
-- that is not there — which is map 0 — so a console built against this protocol
-- still starts a round against a server that has never heard of maps.
function M.parseGameStarting(body)
    return M.u8(body, 2) % M.MAP_COUNT
end

-- body of MAP_CHANGED -> mapId
--
-- Clamped like every other map id that crosses the wire: an out-of-range value
-- would index past MAP_NAMES and take the whole redraw down with it.
function M.parseMapChanged(body)
    return M.u8(body, 1) % M.MAP_COUNT
end

-- body of ROOM_STATE -> ownerSlot, { {slot, flags, name, colour, alive, owner}, ... }
function M.parseRoomState(body)
    local count, ownerSlot = M.u8(body, 1), M.u8(body, 2)
    local players = {}
    for i = 1, count do
        local o = 3 + (i - 1) * M.PLAYER_RECORD
        if o + M.PLAYER_RECORD - 1 > #body then break end
        local p = {
            slot   = M.u8(body, o),
            flags  = M.u8(body, o + 1),
            name   = M.getName(body, o + 2),
            colour = M.u8(body, o + 14),
        }
        p.alive = M.hasFlag(p.flags, M.PLAYER_FLAG_ALIVE)
        p.owner = M.hasFlag(p.flags, M.PLAYER_FLAG_OWNER)
        players[i] = p
    end
    return ownerSlot, players
end

-- body of ROOM_JOINED -> roomId, yourSlot, joinCode
function M.parseRoomJoined(body)
    return M.u16(body, 1), M.u8(body, 3), M.getName(body, 4, M.CODE_LEN)
end

-- body of ROLE_ASSIGNED -> role, impostorCount
function M.parseRoleAssigned(body)
    return M.u8(body, 1), M.u8(body, 2)
end

-- body of TASK_LIST -> { taskId, ... }
function M.parseTaskList(body)
    local count = M.u8(body, 1)
    local ids = {}
    for i = 1, count do
        if 1 + i > #body then break end
        ids[i] = M.u8(body, 1 + i)
    end
    return ids
end

-- body of TASK_PROGRESS -> done, total
function M.parseTaskProgress(body)
    return M.u8(body, 1), M.u8(body, 2)
end

-- body of MEETING_START -> reason, bySlot, bodySlot
function M.parseMeetingStart(body)
    return M.u8(body, 1), M.u8(body, 2), M.u8(body, 3)
end

-- body of EJECTED -> slot (NOBODY if nobody), wasImpostor
function M.parseEjected(body)
    return M.u8(body, 1), M.u8(body, 2) ~= 0
end

-- body of SABOTAGE_START -> kind, timerFrames
function M.parseSabotageStart(body)
    return M.u8(body, 1), M.u16(body, 2)
end

-- body of SABOTAGE_TICK -> timerFrames
function M.parseSabotageTick(body)
    return M.u16(body, 1)
end

-- body of GAME_OVER -> winner, reason
--
-- The reason byte was added after the fact, so a body that does not carry one
-- reads as KILLED — which is what every ending used to be described as anyway.
function M.parseGameOver(body)
    -- `body` is the payload WITHOUT its subtype byte, so the winner is byte 1
    -- and the reason byte 2 — a two-byte body, not three.
    local reason = #body >= 2 and M.u8(body, 2) or M.OVER_REASON.KILLED
    return M.u8(body, 1), reason
end

-- body of MEETING_TICK -> votingOpen, framesLeft (60Hz frames)
function M.parseMeetingTick(body)
    return M.u8(body, 1) ~= 0, M.u16(body, 2)
end

--- body of COOLDOWN_TICK -> killSeconds, meetingSeconds, meetingsLeft
---
--- Already in SECONDS on the wire: this is display data and nothing else does
--- arithmetic on it, so converting from frames is the server's job.
function M.parseCooldownTick(body)
    return M.u8(body, 1), M.u8(body, 2), M.u8(body, 3)
end

-- body of PLAYER_VENT -> slot, vented
function M.parsePlayerVent(body)
    return M.u8(body, 1), M.u8(body, 2) ~= 0
end

-- body of VOTE_TALLY -> { [slot] = votes }, { [voter] = slotVotedFor }
--
-- Two sections. The counts came first and still do; the per-voter detail is
-- APPENDED after them, so nothing about the old half moved. Reading past the end
-- of a message that has no second section is safe by construction: `u8` answers
-- 0 there, which is a voter count of zero and an empty table.
--
-- The second table is what puts a face beside each candidate on the results
-- screen. "Who voted with whom" is most of what the next meeting argues about,
-- and a bare count could never say it.
function M.parseVoteTally(body)
    local count = M.u8(body, 1)
    local tally = {}
    for i = 1, count do
        local o = 2 + (i - 1) * 2
        if o + 1 > #body then break end
        tally[M.u8(body, o)] = M.u8(body, o + 1)
    end

    local base = 2 + count * 2
    local voters = M.u8(body, base)
    local votes = {}
    for i = 1, voters do
        local o = base + 1 + (i - 1) * 2
        if o + 1 > #body then break end
        votes[M.u8(body, o)] = M.u8(body, o + 1)
    end
    return tally, votes
end

-- body of IMPOSTOR_LIST -> { slot, ... }
--
-- Only an impostor's console ever receives this, so merely HAVING it is what
-- says we are one. See M.S2C.IMPOSTOR_LIST.
function M.parseImpostorList(body)
    local count = M.u8(body, 1)
    local slots = {}
    for i = 1, count do
        if 1 + i > #body then break end
        slots[i] = M.u8(body, 1 + i)
    end
    return slots
end

-- =========================================================================
-- THE BUTTON PROMPT BAR
-- =========================================================================
--
-- Three slots along the bottom of every screen: a pad glyph and a short label
-- saying what that button does RIGHT NOW. Menu, lobby, map and task panel all
-- use the same three slots in the same three places, so a player only ever has
-- to learn where to look once.
--
-- It lives HERE, in the protocol module, and that is not laziness. `sync_lua.py`
-- inlines this file ahead of each scene script, so every scene gets its own
-- private copy of the locals below — one implementation, three independent
-- instances, and no globals shared between scenes that could outlive a
-- `Scene.Load`. Duplicating it into three scene scripts would mean three places
-- to fix a prompt that says the wrong thing.
--
-- === Why the labels are dynamic ========================================
--
-- A prompt for an action you cannot take is worse than no prompt at all: it
-- teaches the player that the bar is decoration, and then they stop reading the
-- one that matters. Everything below is rebuilt from what the player can
-- actually do at the position they are actually standing in.

--- Cell indices into the `ui` sheet. Contract with `UIC` in make_art.py.
M.BTN = {
    CROSS = 3, CIRCLE = 4, SQUARE = 5, TRIANGLE = 6,
    START = 19, SELECT = 20, DPAD = 21, L2 = 22, R2 = 23,
}

-- ...and the flat neutral cell, still used for the few things that genuinely
-- ARE tinted rectangles drawn as world sprites. The plate/cap cells that used to
-- be listed here are gone: the plates are authored elements now, so their cells
-- are chosen in make_scenes.py from make_art.py's `UIC` directly.
M.UI_BLOCK = 0

local PROMPT_SLOTS = 3
local PROMPT_Y = 220
local PROMPT_SLOT_X = { 6, 108, 210 }

local promptText = {}      -- slot -> UI element handle for the label
local promptIcon = {}      -- slot -> UI element handle for the pad glyph
local promptLabel = {}     -- slot -> what is currently written there
local promptCell = {}      -- slot -> which glyph is currently shown

--- Bind the bar to a canvas. Safe to call with a canvas that has no prompt
--- elements: the bar simply never draws, and everything else still works.
---
--- BOTH halves of a slot are authored elements now. The glyphs used to be
--- sprites created here and re-framed with `Sprite.SetFrame`; they are
--- `prompticon1..3` in the same canvas as the labels, laid out by
--- make_scenes.py's `build_prompt_icons`, and re-framed with `UI.SetFrame`.
---
--- Three things came free with that. The bar no longer spends three of the
--- 128 sprite slots the avatars are competing for; it no longer depends on
--- `_G.LAYER` existing (a sprite layer number that the menu and lobby had to
--- guess at, and which decided whether the glyph drew in front of its own
--- plate); and the glyph is where you can see it in the editor, beside the
--- label it belongs to, instead of at coordinates written in this file.
function M.initPrompts(canvasName)
    local canvas = UI.FindCanvas(canvasName)
    for i = 1, PROMPT_SLOTS do
        promptText[i] = canvas >= 0 and UI.FindElement(canvas, "prompt" .. i) or -1
        promptIcon[i] = canvas >= 0 and UI.FindElement(canvas, "prompticon" .. i) or -1
        if promptText[i] >= 0 then UI.SetVisible(promptText[i], false) end
        if promptIcon[i] >= 0 then UI.SetVisible(promptIcon[i], false) end
        promptLabel[i] = nil
        promptCell[i] = nil
    end
end

--- Show a list of `{ button, label }` pairs, or nothing.
---
--- Anything past the third pair is dropped rather than wrapped: there is no
--- fourth slot, and a bar that grew a second row would move the first one.
---
--- Every write is guarded by what is already on screen. This is called from
--- `onUpdate` at several hertz, and `UI.SetText` re-lays a string out on the
--- GPU — repainting three unchanged captions every frame is a cost paid for
--- nothing.
function M.setPrompts(list)
    for i = 1, PROMPT_SLOTS do
        local entry = list and list[i]
        local h = promptText[i]
        local icon = promptIcon[i]
        if entry then
            if promptLabel[i] ~= entry[2] then
                promptLabel[i] = entry[2]
                if h and h >= 0 then
                    UI.SetText(h, entry[2])
                    UI.SetVisible(h, true)
                end
            end
            if icon and icon >= 0 and promptCell[i] ~= entry[1] then
                promptCell[i] = entry[1]
                UI.SetFrame(icon, entry[1])
                UI.SetVisible(icon, true)
            end
        elseif promptLabel[i] ~= nil or promptCell[i] ~= nil then
            promptLabel[i] = nil
            promptCell[i] = nil
            if h and h >= 0 then UI.SetVisible(h, false) end
            if icon and icon >= 0 then UI.SetVisible(icon, false) end
        end
    end
end

function M.hidePrompts() M.setPrompts(nil) end

-- =========================================================================
-- HUD CHROME
-- =========================================================================
--
-- A "plate": a bevelled metal bar with shaped end caps, for text to sit on.
--
-- This exists because a HUD of bare white text floating on the map is not a
-- HUD, it is a debug overlay — and on a busy tilemap it is genuinely hard to
-- read, because the letters have no consistent background.
--
-- THE PLATES ARE AUTHORED. Their rects live in make_scenes.py beside the text
-- rects they back, which is the whole point: they used to be sprites placed
-- from a rect table in scene_game.lua while the words on them were UI elements
-- positioned in the generator — two systems that cannot see each other, laid
-- out in two files, kept in agreement by hand. They were not in agreement, and
-- the game-over prose started six pixels outside the panel it belonged in.
--
-- What is left here is lookup and state.

--- Find a plate authored in a canvas, as a list of element handles.
---
--- `prefix` names either a three-piece pill (`prefix_l`, `prefix_m`,
--- `prefix_r`) or a single-element panel (`prefix`). Both come back as a plain
--- list, so `showPlate` and `tintPlate` work on either without knowing which.
---
--- Returns nil when the canvas or the pieces are not there. Every caller
--- tolerates that: a HUD without its backing is still a readable HUD, which is
--- the right way for a missing asset to fail.
function M.findPlate(canvasName, prefix)
    local c = UI.FindCanvas(canvasName)
    if c < 0 then return nil end

    -- A one-piece panel first: `plate_overbody` is a single stretched cell,
    -- because the caps are 16x16 art with a rounded END drawn for a one-line
    -- pill bar. Stretched to the height of a 96px dialog that corner is not a
    -- rounded box, it is a 16px vertical smear down each side.
    local one = UI.FindElement(c, prefix)
    if one >= 0 then return { one } end

    local p = {}
    local l = UI.FindElement(c, prefix .. "_l")
    local m = UI.FindElement(c, prefix .. "_m")
    local r = UI.FindElement(c, prefix .. "_r")
    if l < 0 or m < 0 or r < 0 then return nil end
    p[1], p[2], p[3] = l, m, r
    return p
end

-- Both shapes are just a list of handles, so show/tint work on either. Counting
-- the table rather than assuming three is what lets a panel share them.
function M.showPlate(p, on)
    if not p then return end
    for i = 1, #p do UI.SetVisible(p[i], on and true or false) end
end

function M.tintPlate(p, r, g, b)
    if not p then return end
    for i = 1, #p do UI.SetColor(p[i], r, g, b) end
end


-- There is no `require` on the console, and each script runs in its own
-- environment table whose metatable only forwards READS to _G — so a plain
-- `PSXSUS = M` would land in this file's private environment, invisible to every
-- other script. Writing through _G explicitly is what publishes it.
--
-- Attach this file to the scene BEFORE the scripts that use it: splashpack Lua
-- files execute in order, and a scene script running first would see nil.
_G.PSXSUS = M

-- Still returned, so desktop tests can load it in the ordinary way.
-- === scene ===============================================

-- PSXSUS lobby — the scene script.
--
-- Attach to the LOBBY scene's PSXSceneExporter, AFTER psxsus_protocol.lua.
-- `lobby_input.lua` drives it from the pad, because scene scripts get no
-- per-frame callback (only methodIds 1/2/3/4: onSceneCreationStart /
-- onSceneCreationEnd / onNetEvent / onNetData).
--
-- The server decides everything that matters: who is in a room, who owns it,
-- which map it is on, and when the game starts. This file asks and displays; it
-- never assumes its request succeeded. Pressing Start does not change the
-- screen — the screen changes when GAME_STARTING arrives.
--
-- === Two engine facts this file is shaped by ==============================
--
-- 1. `Persist` stores ONE `long` per key and holds SIXTEEN keys, silently
--    dropping the seventeenth (luaapi.cpp: `lua_Number value = lua.toNumber(2)`
--    over `PersistEntry s_persistData[16]`). It cannot hold a name or a join
--    code — `Persist.Set("name", "RED")` stores 0 — so shared state lives in the
--    `_G.SUS` table below instead. Lua files each get a private environment
--    whose metatable forwards READS to _G, so an explicit `_G.SUS` is how two
--    files share anything at all.
--
-- 2. `Net.SendData` returns false until the handshake completes
--    (`sendAppData`: `if (m_state != State::Connected) return false`). Connect()
--    takes a round trip, so anything sent from onSceneCreationEnd is DROPPED.
--    Hence the CONNECTING view: nothing is sent until Net.IsConnected().
--
-- Console Lua has no `math` and no `require`, and every number is a `long` —
-- see psxsus_protocol.lua.

local P = nil
local handlers = nil

-- One full page of rooms in one packet (4 + 15*16 = 244 <= 256). A literal so
-- this file cannot fail at load; ready() checks it against the protocol.
local ROW_COUNT = 15

-- ...but only NINE of them are on screen at once, and that is a hard limit
-- rather than a preference. The authored `Font` is 16x19, so the whole 240px
-- display is twelve rows — a title, a status line and the button prompt bar
-- leave nine. The scene is built with nine row elements (make_scenes.py derives
-- the same number from the same constants and refuses to write a layout that
-- does not fit) and the room list scrolls a window over the page.
--
-- Fifteen is a PACKET size, not a screen size, and using it as one is how the
-- first version drew rows at y=236, 252 and 268 on a 240px screen.
local VISIBLE_ROWS = 9

-- dt is 4.12 fixed point where 4096 == one 30Hz frame, so a real second is
-- 30*4096. Timers here accumulate raw dt units and never convert to seconds
-- first: LUA_NUMBER is a long, so `dt / 4096` is 0 at anything above 30fps.
local DT_SECOND = 30 * 4096
-- Long enough that a healthy link answers well inside it, short enough that a
-- lost reply costs a noticeable pause rather than the session.
local ANNOUNCE_RETRY = 2 * DT_SECOND
-- How often a console stuck on CONNECTING re-announces itself to the PC. See
-- SusTickLobby for why this exists at all. Long enough that a link coming up
-- normally is never interrupted by it, short enough that a player who started
-- the emulator's SIO1 client late is not left staring at the screen.
local RECONNECT_RETRY = 3 * DT_SECOND
-- How long a room with an empty roster waits before saying so on screen.
local ROSTER_PATIENCE = 6 * DT_SECOND
-- Used when the send itself was refused (reliable queue full), which resolves in
-- a frame or two — waiting a full interval for that would be pure latency.
local ANNOUNCE_BACKOFF = DT_SECOND / 4

-- MAP is new: the room owner picks the ship before creating the room. The first
-- six values are unchanged, because the host tests name them by number.
_G.VIEW = { CONNECTING = 0, ROOMS = 1, CODE = 2, IN_ROOM = 3, STARTING = 4,
            NAME = 5, MAP = 6 }
local VIEW = _G.VIEW

--- Shared mutable state. A table, not Persist: Persist is numbers-only and
--- 16-deep, and two of these are strings.
_G.SUS = {
    view = VIEW.CONNECTING,
    cursor = 1,
    mySlot = -1,
    roomId = 0,
    joinCode = "",
    isOwner = false,
    playerName = "",       -- picked at random on arrival; see pickName()
    namedYet = false,      -- has the player actually confirmed one?
    announced = false,     -- has a room list actually ARRIVED? (not: have we asked)
    announceWait = 0,      -- dt units since the last unanswered announce attempt
    rejoining = false,     -- came back from a finished round, still in the room
    connectWait = 0,       -- dt units spent on the CONNECTING screen
    rosterWait = 0,        -- dt units since the last unanswered roster request
    emptyRoomWait = 0,     -- dt units spent in a room whose roster is empty
    reconnectWait = 0,     -- dt units until the next CONNECTING re-announce
    rooms = {},
    page = 0,              -- room-list page we are showing
    pageCount = 1,         -- how many the server says there are
    players = {},
    codeChars = { 1, 1, 1, 1 },
    codePos = 1,
    nameChars = nil,       -- rotary name editor: one alphabet index per column
    namePos = 1,
    mapId = 0,             -- which ship a room we CREATE will be played on
    roomMapId = 0,         -- which ship the room we are IN is on
    mapPickMode = "host",  -- what the ship picker's CROSS means: "host"|"change"
    private = false,       -- what the map picker will create
    -- Set by a failed request so the reason survives the next redraw. A message
    -- overwritten by the periodic refresh a third of a second later is a message
    -- nobody reads.
    notice = nil,
    noticeWait = 0,
}
local S = _G.SUS

-- The name alphabet. A pad has no keyboard, so a name is dialled in the same way
-- a join code is: one column at a time. Space is last so trailing blanks are easy
-- to reach and a short name is quick to finish.
_G.NAME_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 "
local NAME_ALPHABET = _G.NAME_ALPHABET
local NAME_COLS = 8    -- fits the 12-char server cap with room to spare on screen

--- Names to start from, so nobody is "PLAYER" and nobody arrives blank.
---
--- A lobby of unnamed players is a vote screen you cannot use — the whole
--- meeting is matching a name to a colour, and a room where three people are
--- called the same thing is a round nobody can win.
local START_NAMES = {
    "RED", "BLUE", "LIME", "PINK", "AMBER", "CYAN",
    "MINT", "PLUM", "RUST", "SNOW", "ASH", "TEAL",
}

--- One of the above, chosen from something that differs between consoles.
---
--- There is no `math.random` and no clock the lobby can read before the link is
--- up, so the seed is the SLOT the server hands us — which is unique in the room
--- by construction, and therefore gives every player in it a different name.
--- Before a slot exists it falls back to the first name, which is only ever seen
--- for the moment before joining.
local function pickName(seed)
    if not seed or seed < 1 then seed = 1 end
    return START_NAMES[((seed - 1) % #START_NAMES) + 1]
end

-- === remembering the name ================================================
--
-- The name has to survive two different kinds of forgetting, and each one needs
-- its own mechanism.
--
-- ACROSS A SCENE LOAD. `Scene.Load` wipes the Lua state, and `_G.SUS` with it,
-- so a console coming back from a round no longer knows what it is called. The
-- server is not a copy to fall back on: it is told the name ONCE, on the way in,
-- and holds it against the SESSION -- so anything that costs us the session
-- costs us the name as well. `Persist` is the only thing that lives through the
-- load, and it stores ONE NUMBER per key: `Persist.Set("name", "RED")` stores 0.
--
-- So the name is packed into numbers. Six bits per column (the alphabet is 37
-- characters, and 37 < 64), four columns per key, two keys for the eight
-- columns. What is stored is the alphabet INDEX, 1..37 and never 0, so that no
-- saved name can encode to zero and a missing key -- Persist.Get answers nil --
-- is the only thing that reads back as "nothing saved here".
--
-- ACROSS A POWER CYCLE. Persist dies with the console; that is what the memory
-- card below is for.
local PERSIST_NAME_HI = "nmhi"    -- columns 1-4
local PERSIST_NAME_LO = "nmlo"    -- columns 5-8
local NAME_RADIX = 64             -- one column per six bits

--- Alphabet index of a single character, defaulting to the space.
local function nameIndexOf(c)
    if c == "" then return #NAME_ALPHABET end
    local at = string.find(NAME_ALPHABET, c, 1, true)
    return at or #NAME_ALPHABET
end

--- Four columns of `s`, starting at `from`, as one number.
local function packQuad(s, from)
    local v = 0
    for i = from, from + 3 do
        v = v * NAME_RADIX + nameIndexOf(string.sub(s, i, i))
    end
    return v
end

--- Expand one packed quad into four alphabet indices, appending them to `out`.
---
--- The remainder is subtracted BEFORE dividing, which is the same exact-shift
--- idiom parseRoomList uses to pull the map bits out of a room's flags. It is
--- not decoration: `/` is only integer division because LUA_NUMBER is a long,
--- and on any Lua where it is not, `v / 64` leaves a fraction behind, the digit
--- comes out as something like 34.5, and `string.sub` refuses it outright --
--- a hard error on the lobby's first frame rather than a name that reads wrong.
--- Subtracting first makes the division exact, so it holds either way.
local function unpackQuad(v, out)
    local q = { 0, 0, 0, 0 }
    for i = 4, 1, -1 do
        local d = v % NAME_RADIX
        q[i] = d
        v = (v - d) / NAME_RADIX
    end
    for i = 1, 4 do out[#out + 1] = q[i] end
end

--- The name held in two packed quads, with trailing spaces trimmed the way
--- nameString() trims them.
local function unpackName(hi, lo)
    local idx = {}
    unpackQuad(hi, idx)
    unpackQuad(lo, idx)
    local s = ""
    for i = 1, NAME_COLS do
        local at = idx[i] or 0
        if at < 1 or at > #NAME_ALPHABET then at = #NAME_ALPHABET end
        s = s .. string.sub(NAME_ALPHABET, at, at)
    end
    while #s > 0 and string.sub(s, #s) == " " do s = string.sub(s, 1, #s - 1) end
    return s
end

--- Put the name somewhere `Scene.Load` cannot reach. Two Persist writes and no
--- allocation, so it is called on every change rather than at chosen moments.
local function rememberName(s)
    if not (Persist and Persist.Set) then return end
    Persist.Set(PERSIST_NAME_HI, packQuad(s, 1))
    Persist.Set(PERSIST_NAME_LO, packQuad(s, 5))
end

--- The name from before the last scene load, or nil on a cold start.
local function recallName()
    if not (Persist and Persist.Get) then return nil end
    local hi = Persist.Get(PERSIST_NAME_HI)
    local lo = Persist.Get(PERSIST_NAME_LO)
    -- A stored quad always has a non-zero leading index, so zero-or-nil means
    -- "never written" rather than "written as blank".
    if not hi or not lo or hi == 0 then return nil end
    local s = unpackName(hi, lo)
    if s == "" then return nil end
    return s
end

--- Called by lobby_input.lua when the player accepts a name.
_G.SusRememberName = rememberName

-- === the memory card =====================================================
--
-- The smallest useful use of a card: ONE save holding ONE string, written when
-- the player asks for it and read once, on a cold start, as the lobby opens.
--
-- Nothing here formats and nothing here deletes. `MemCard.Save` finds a free
-- file by itself, so a card arrives and leaves with everything else on it
-- untouched, and a card with no PSXSUS save on it is simply a card we read
-- nothing from. There is deliberately no "format card" path anywhere in PSXSUS:
-- the only destructive call the API offers is one this game never makes.
--
-- Every one of these calls BLOCKS for the duration of the card access, so none
-- of them may run per frame. The save is deferred by one frame in
-- lobby_input.lua so the message announcing it reaches the screen first.
local CARD_PORT = 0                     -- slot 1
local CARD_KEY = "NAME"
local CARD_TITLE = "PSXSUS PLAYER NAME"

--- The saved name, or nil if there is no card, no save, or nothing usable in it.
--- Never fails loudly: a card we cannot read is still a lobby you can play from.
local function loadNameFromCard()
    if not (MemCard and MemCard.Load and MemCard.IsPresent) then return nil end

    local present, presentErr = MemCard.IsPresent(CARD_PORT)
    if presentErr then
        Debug.Log("PSXSUS name: card check failed - " .. presentErr)
        return nil
    end
    if not present then return nil end

    local data, err = MemCard.Load(CARD_PORT, CARD_KEY)
    if not data then
        -- Not worth putting on screen. The overwhelmingly common reason is that
        -- this player has never saved a name, which is not a fault.
        if err then Debug.Log("PSXSUS name: no name on card - " .. err) end
        return nil
    end
    if type(data) ~= "table" or type(data.name) ~= "string" then return nil end

    local s = data.name
    if #s > NAME_COLS then s = string.sub(s, 1, NAME_COLS) end
    if s == "" then return nil end
    return s
end

--- Write the current name to the card. Always returns a line for the status bar.
---
--- "It did not save", with no reason, is the one answer a player cannot act on,
--- so every distinguishable failure gets its own sentence. They are SHORT
--- because the authored font puts about 32 characters on the status line; the
--- detail goes to the log rather than off the side of the screen.
_G.SusSaveNameToCard = function()
    if not (MemCard and MemCard.Save) then return "NO CARD SUPPORT" end
    if S.playerName == "" then return "NOTHING TO SAVE" end

    local present, presentErr = MemCard.IsPresent(CARD_PORT)
    if presentErr then
        Debug.Log("PSXSUS name: card check failed - " .. presentErr)
        return "CARD ERROR - SEE LOG"
    end
    if not present then return "NO CARD IN SLOT 1" end

    local ok, err = MemCard.Save(CARD_PORT, CARD_KEY,
                                 { name = S.playerName }, CARD_TITLE)
    if not ok then
        Debug.Log("PSXSUS name: save failed - " .. (err or "unknown"))
        return "SAVE FAILED - SEE LOG"
    end
    return "SAVED " .. S.playerName
end

local ui = {}
local canvas = -1

-- === UI helpers ==========================================================

local function show(name, visible)
    local h = ui[name]
    if h and h >= 0 then UI.SetVisible(h, visible) end
end

local function text(name, s)
    local h = ui[name]
    if h and h >= 0 then UI.SetText(h, s) end
end

local function rowName(i) return "row" .. i end

local function clearRows()
    for i = 1, ROW_COUNT do show(rowName(i), false) end
end

local function row(i, s)
    show(rowName(i), true)
    text(rowName(i), s)
end

-- === link health =========================================================
--
-- What used to be here was four rows of raw counters, on every screen, all the
-- time. They earned their place — a dead serial link presented as one frozen
-- word for three sessions — but they are a DEVELOPER's readout, and shipping
-- them means every player reads "RX 4192 TX 210 IRQ 533 FRM 12" while trying to
-- pick a room.
--
-- So: one short line, only when something is actually wrong, phrased as
-- something a player can act on. The full dump still exists, behind SELECT on
-- the connecting screen — which is exactly where a link that never comes up
-- leaves you, so the diagnostics are reachable in the state that needs them.

local NET_STATE = {
    [0] = "DISCONNECTED",
    [1] = "CONNECTING TO SERVER...",
    [2] = "CONNECTED",
    -- Two of these are TERMINAL and silent: the engine latches them in
    -- onHelloAck and preTick then returns early forever, so the console stops
    -- talking entirely. Showing "connecting" in that state is a lie that costs
    -- hours — the link is not coming back, and the player needs to know which.
    [3] = "VERSION MISMATCH - REBUILD THE DISC",
    [4] = "SCENE MISMATCH - RE-EXPORT THE SCENE",
}

--- A short, plain-language warning, or nil when the link is well.
---
--- Every string fits in 34 characters: they are drawn into one row on a 320px
--- screen, and the first thing a real console ever reported was a warning
--- running off the edge of the display, which cost a whole test cycle.
local function linkTrouble()
    if not Net.Stats then return nil end
    local s = Net.Stats()
    if not s then return nil end

    if (s.irqStorms or 0) > 0 then return "LINK BUSY - PLAY MAY STUTTER" end
    -- Framing errors mean the two ends disagree about bit timing: a cable, a
    -- baud rate or a bad adapter. Nothing the game can pace its way out of, and
    -- a different fault from overruns, which are our own latency.
    if (s.rxFramingErrors or 0) > 0 then return "CHECK THE CABLE - BAD SIGNAL" end
    if (s.rxOverflows or 0) > 0 then return "LINK OVERLOADED" end
    local rx = s.bytesRx or 0
    if rx > 2000 and (s.rttSamples or 0) == 0 then return "SERVER NOT ANSWERING" end

    -- A BACKLOG is the honest measure of a link that cannot keep up: we have
    -- bytes queued and they are not draining.
    --
    -- What used to be here was `goodput < 500`, and it was wrong in a way that
    -- made the lobby cry wolf permanently. `goodput` is bytes we ACTUALLY SENT
    -- per second (netlink.cpp: m_txWindowBytes over the window) — it measures
    -- offered load, not capacity. The lobby is a menu: replication is off, and
    -- once the room list has arrived the console sends nothing but a periodic
    -- Ping. So goodput sits near zero because there is nothing to say, an idle
    -- link reads exactly like a dying one, and "SLOW LINK" was on screen for the
    -- entire session. You cannot measure a link's speed without using it.
    local cap = s.txCapacity or 0
    if cap > 0 and (s.txPending or 0) * 4 > cap then return "LINK IS BACKED UP" end
    -- Latency, which IS measurable while idle: the Ping keeps going out.
    if (s.rttSamples or 0) > 0 and (s.rttMillis or 0) > 1000 then
        return "SLOW LINK"
    end

    local fps = _G.SusFps
    if fps and fps < 12 then return "RUNNING SLOWLY" end
    return nil
end

--- The full counter dump, five rows. Only ever drawn on the diagnostics page.
---
--- Reading it when the console will not connect:
---   IRQ 0 and RX 0        the RX interrupt never fired
---   RX rising, FRM 0      bytes arrive, no frame ever completes
---   FRM rising            the two ends disagree about bit timing (cable, baud)
---   OVR rising            the 8-byte hardware FIFO is overrunning
---   IRQ close to RX       per-byte interrupts (should be about RX/8)
---   BAUD                  must match the bridge's dropdown exactly
---
--- Reading it when the console DIES MID-GAME rather than failing to connect — a
--- different fault with a different row:
---   RXD climbing          the receive interrupt is being destroyed and revived.
---                         psyqo's pad driver acknowledges the controller IRQ with
---                         a read-modify-write on I_STAT, which can acknowledge
---                         OURS by accident; SIO_STAT.9 is sticky and I_STAT.8 is
---                         edge-triggered, so that kill is permanent unless the
---                         edge is re-created. A climbing count WITH the game
---                         still playing is the fix working. It killed the link
---                         outright before.
---   PAD not 2             the pad poll is being re-registered. Exactly 2, one per
---                         player, for the whole boot. Higher means every scene
---                         load adds blocking SIO0 work to every frame forever.
---   HEAP climbing         something is accumulating on a 2MB machine with no
---                         virtual memory. Flat rules out the whole family of
---                         leak theories, which is worth knowing cheaply.
---
--- All three are about faults that arrive LATE, which is why they share a row: a
--- console that plays for ten seconds and then stops cannot be diagnosed by any
--- counter that only describes the present moment. HEAP was exposed to Lua for
--- exactly this and then never displayed anywhere, so it had never once been
--- readable during play — precisely the window it exists to cover.
_G.SusDiagnostics = function()
    if not Net.Stats then return nil end
    local s = Net.Stats()
    if not s then return nil end
    return string.format("RX %d TX %d IRQ %d FRM %d", s.bytesRx, s.bytesTx,
                         s.rxIrqs, s.frames),
           string.format("OVR %d FRM %d CRC %d RSY %d", s.rxOverrunErrors or 0,
                         s.rxFramingErrors or 0, s.crcErrors, s.resyncs),
           string.format("TXP %d DRP %d FPS %d BAUD %d", s.txPending or 0,
                         s.snapshotsDropped or 0, _G.SusFps or 0, s.baud or 0),
           string.format("OUT %d IN %d RTT %d N%d", s.goodput or 0,
                         s.inbound or 0, s.rttMillis or 0, s.rttSamples or 0),
           string.format("RXD %d PAD %d HEAP %dK", s.rxRevivals or 0,
                         s.padInits or 0, s.heapKB or 0)
end

-- === notices =============================================================

--- Say something on the status line and keep it there for a moment.
---
--- The lobby redraws twice a second, so a message written straight to the status
--- row is gone before it can be read. Anything the player must actually see goes
--- through here, and the redraw stamps it back over whatever the view wanted to
--- say until it expires.
local NOTICE_HOLD = 3 * DT_SECOND

_G.SusNotice = function(msg)
    S.notice = msg
    S.noticeWait = msg and NOTICE_HOLD or 0
    SusRedraw()
end

_G.SusTickNotice = function(dt)
    if not S.notice then return end
    S.noticeWait = S.noticeWait - (dt or 0)
    if S.noticeWait <= 0 then
        S.notice = nil
        SusRedraw()
    end
end

--- The sticky form, used by lobby_input.lua's retry path: it sets a message
--- while a request is being retried and clears it with nil when the request
--- finally goes. It must NOT expire on its own, or the screen would go back to
--- looking idle while a press is still stuck in the queue.
_G.SusSetStatus = function(msg)
    if S.notice == msg then return end
    S.notice = msg
    -- A very large hold rather than a special case: the caller clears it.
    S.noticeWait = msg and (600 * DT_SECOND) or 0
    SusRedraw()
end

-- === rendering ===========================================================

local diagPage = false

_G.SusToggleDiagnostics = function()
    diagPage = not diagPage
    SusRedraw()
end

--- How long the console waits before admitting something is wrong.
---
--- Playtesters reported the connecting screen "just getting stuck without user
--- facing errors". It genuinely can: state 1 is not an error state, so nothing
--- in the engine ever latches a failure — a bridge that is not running, a cable
--- in the wrong port and a server that is simply slow all look identical, and
--- all three look like the game is still working on it. Silence forever is the
--- worst of the available answers, so after a while the screen says what it
--- actually knows and what to check.
local CONNECT_PATIENCE = 8 * DT_SECOND
local CONNECT_GIVE_UP = 20 * DT_SECOND

local function drawConnecting()
    clearRows()
    text("title", "PSXSUS")
    local st = Net.State and Net.State() or 1
    local msg = NET_STATE[st] or ("LINK STATE " .. st)
    if st == 2 then
        -- Connected but still on this screen means the handshake worked and the
        -- room list request has not been answered yet (or never sent).
        msg = "CONNECTED - LOADING ROOMS..."
    end

    -- Nothing below overrides a TERMINAL state (3 and 4): those already name the
    -- exact fault, and "check the cable" on a version mismatch would send the
    -- player looking in the wrong place.
    if st ~= 3 and st ~= 4 and S.connectWait >= CONNECT_PATIENCE then
        local giving_up = S.connectWait >= CONNECT_GIVE_UP
        if st == 2 then
            -- The link is UP. So this is the server not answering, which is a
            -- different fault with a different fix.
            row(7, giving_up and "THE SERVER IS NOT ANSWERING"
                             or  "STILL WAITING FOR THE SERVER")
            row(8, giving_up and "IT MAY BE DOWN, OR ON ANOTHER VERSION" or "")
        else
            row(7, giving_up and "NO REPLY FROM THE LINK"
                             or  "STILL TRYING TO REACH THE SERVER")
            row(8, giving_up and "CHECK THE CABLE AND THE PC BRIDGE" or "")
        end
        if giving_up then row(9, "SELECT SHOWS THE LINK COUNTERS") end
    end

    if diagPage then
        local a, b, c, d, e = SusDiagnostics()
        if a then
            row(2, a); row(3, b); row(4, c); row(5, d); row(6, e)
        else
            row(3, "NO LINK COUNTERS AVAILABLE")
        end
        text("status", msg)
        return
    end

    row(5, "        CONNECTING TO THE SERVER")
    text("status", msg)
end

local function drawRoomList()
    clearRows()
    if S.pageCount > 1 then
        text("title", string.format("ROOMS - %s     PAGE %d/%d",
                                    S.playerName, S.page + 1, S.pageCount))
    else
        text("title", "ROOMS - " .. S.playerName)
    end

    if #S.rooms == 0 then
        row(4, "     NO ROOMS OPEN RIGHT NOW")
        row(6, "     HOST ONE AND TELL PEOPLE")
        row(7, "     YOUR FOUR-LETTER CODE")
        text("status", "R1 CODE   SELECT NAME   O BACK")
        return
    end

    -- Scroll a VISIBLE_ROWS window over the page so the cursor is always on
    -- screen. No `math` on the console, so the clamp is spelled out.
    local first = 1
    if S.cursor > VISIBLE_ROWS then first = S.cursor - VISIBLE_ROWS + 1 end
    local last = first + VISIBLE_ROWS - 1
    if last > #S.rooms then last = #S.rooms end

    for i = first, last do
        local r = S.rooms[i]
        local mark = (i == S.cursor) and ">" or " "
        local lock = r.private and "*" or " "
        -- Name, then how full, then which ship. The map matters when choosing: a
        -- player who does not know the Hulk would rather join a Rim room.
        --
        -- Budgeted at 32 characters, not 40: the font is PROPORTIONAL and
        -- averages 9.15px per uppercase letter, so 304px is about 32 of them.
        -- The map name is abbreviated for the same reason.
        row(i - first + 1, string.format("%s%s%-10s %2d/10 %s", mark, lock,
                                         string.sub(r.name or "?", 1, 10),
                                         r.playerCount or 0,
                                         P.mapShort(r.mapId)))
    end

    -- Say there is more, or a player at the bottom of a full screen has no way
    -- to know the list continues. The BUTTONS are on the prompt bar now; this
    -- line carries what the bar has no room for, and where you are in the list —
    -- which on a public server is the only way to tell a short list from page
    -- one of forty.
    if S.pageCount > 1 then
        -- L2/R2, matching lobby_input.lua. L1 is "host a PRIVATE room", and
        -- naming the wrong shoulder button here is the kind of mistake nobody
        -- catches until somebody hosts a private room by accident.
        text("status", string.format("PAGE %d/%d  L2/R2 TURN  SELECT NAME",
                                     S.page + 1, S.pageCount))
    elseif #S.rooms > VISIBLE_ROWS then
        text("status", string.format("%d/%d   R1 CODE   SELECT NAME",
                                     S.cursor, #S.rooms))
    else
        text("status", "R1 CODE   SELECT NAME   O BACK")
    end
end

local function codeString()
    local s = ""
    for i = 1, P.CODE_LEN do
        s = s .. string.sub(P.CODE_ALPHABET, S.codeChars[i], S.codeChars[i])
    end
    return s
end

_G.SusCodeString = codeString

local function drawCode()
    clearRows()
    text("title", "JOIN BY CODE")
    local code = codeString()
    -- Wide spacing and a caret under the character being edited, so it is
    -- obvious which of the four the d-pad is changing.
    -- Bracketed rather than carted, for the reason spelled out in drawName: the
    -- font is proportional, so a caret on the line below cannot stay under the
    -- character it points at.
    local letters = ""
    for i = 1, P.CODE_LEN do
        local c = string.sub(code, i, i)
        if i == S.codePos then
            letters = letters .. " [" .. c .. "]"
        else
            letters = letters .. "  " .. c .. " "
        end
    end
    row(4, "        " .. letters)
    row(8, "     ASK THE HOST FOR THEIR CODE")
    text("status", "")
end

-- === name entry ==========================================================

--- Seed the rotary editor from the current name, so opening it starts where the
--- player already is instead of blanking what they had.
_G.SusBeginNameEdit = function()
    local chars = {}
    for i = 1, NAME_COLS do
        local c = string.sub(S.playerName, i, i)
        local idx = 1
        if c ~= "" then
            local at = string.find(NAME_ALPHABET, c, 1, true)
            if at then idx = at end
        else
            idx = #NAME_ALPHABET   -- the space, i.e. "nothing here"
        end
        chars[i] = idx
    end
    S.nameChars = chars
    S.namePos = 1
    S.view = VIEW.NAME
end

local function nameString()
    if not S.nameChars then return S.playerName end
    local s = ""
    for i = 1, NAME_COLS do
        local idx = S.nameChars[i] or 1
        s = s .. string.sub(NAME_ALPHABET, idx, idx)
    end
    -- Trailing spaces are how you spell a short name on a fixed set of columns,
    -- so they are trimmed rather than sent to the server.
    while #s > 0 and string.sub(s, #s) == " " do s = string.sub(s, 1, #s - 1) end
    return s
end

_G.SusNameString = nameString

local function drawName()
    clearRows()
    text("title", "YOUR NAME")
    -- The column being edited is BRACKETED, not marked by a caret on the line
    -- below.
    --
    -- The font is PROPORTIONAL: an "I" advances 4px and an "M" 14, so a caret
    -- built by pairing one character per column with the letters above it drifts
    -- further out of line with every narrow letter typed, and by the eighth
    -- column it is pointing at the wrong one. Brackets travel with the letter and
    -- cannot come apart from it.
    local letters = ""
    for i = 1, NAME_COLS do
        local idx = S.nameChars and S.nameChars[i] or 1
        local c = string.sub(NAME_ALPHABET, idx, idx)
        if c == " " then c = "_" end        -- an empty column has to be visible
        if i == S.namePos then
            letters = letters .. "[" .. c .. "]"
        else
            letters = letters .. " " .. c .. " "
        end
    end
    row(4, "  " .. letters)
    local shown = nameString()
    row(8, "   OTHERS SEE: " .. (shown ~= "" and shown or "(EMPTY)"))
    -- The card hint goes on the STATUS line rather than the prompt bar.
    -- PROMPT_SLOTS is 3 and setPrompts silently drops a fourth entry, so
    -- DIAL/OK/BACK already fills the bar. It also puts the hint exactly where
    -- the save's own progress messages appear, which is the right place to have
    -- been looking when one shows up.
    text("status", "TRIANGLE = SAVE NAME TO CARD")
end

-- === map picker ==========================================================
--
-- Shown before a room is created, not after. Which ship you are about to host on
-- is a decision, and a room whose map can still change once people have joined
-- is a room people join and then leave.

local MAP_BLURB = {
    "ONE LONG SPINE. MANY DEAD ENDS.",
    "A RING. YOU CAN ALWAYS RUN TWO WAYS.",
    "A DEEP MINE. FOUR LEVELS, TWO SHAFTS.",
}

--- Open the ship picker, either to create a room or to move an existing one.
---
--- The two uses share a screen because they are the same choice, but they must
--- not share an outcome: one sends CreateRoom and the other SetMap. `mapPickMode`
--- is what CROSS reads to tell them apart, and it is set HERE rather than
--- inferred from the view we came from - "am I in a room" changes underneath a
--- player who is dropped mid-decision, and picking a ship should not create a
--- second room because a roster packet went missing while the picker was open.
_G.SusBeginMapPick = function(mode)
    S.mapPickMode = mode or "host"
    S.cursor = (S.mapPickMode == "change" and S.roomMapId or S.mapId) + 1
    S.view = VIEW.MAP
end

local function drawMapPick()
    clearRows()
    local changing = S.mapPickMode == "change"
    if changing then
        text("title", "CHANGE SHIP")
    else
        text("title", S.private and "HOST - PRIVATE" or "HOST A GAME")
    end
    for i = 1, P.MAP_COUNT do
        local mark = (S.cursor == i) and "  > " or "    "
        row(2 + (i - 1) * 3, mark .. P.MAP_NAMES[i])
        row(3 + (i - 1) * 3, "      " .. (MAP_BLURB[i] or ""))
    end
    -- On the status line rather than a tenth row: three maps at two rows each
    -- already fill rows 2..9, and this is a property of the room being created
    -- rather than a fourth thing to choose between.
    if changing then
        text("status", "EVERYONE IN THE ROOM MOVES WITH YOU")
    else
        text("status", S.private and "PRIVATE - REACHABLE ONLY BY CODE"
                                  or "PUBLIC - LISTED FOR EVERYONE")
    end
end

-- === in a room ===========================================================

local function drawRoomState()
    clearRows()
    -- Every field here is defensive on purpose. This screen is drawn from data
    -- that crossed a serial cable, and a corrupted frame that still parses can
    -- leave a nil name or a nil join code. A Lua error thrown midway through a
    -- draw does not fail loudly — it abandons the REST of the draw, so the rows
    -- already written stay on screen and the title and status never appear. That
    -- presents as "some names showed up and the code and prompt vanished", which
    -- looks like a UI bug and is actually a link bug.
    local code = S.joinCode
    if type(code) == "string" and code ~= "" then
        text("title", string.format("%s    CODE %s", P.mapName(S.roomMapId), code))
    else
        text("title", P.mapName(S.roomMapId))
    end

    -- TWO PLAYERS PER ROW.
    --
    -- Ten players do not fit in nine rows, and the roster is the one screen in
    -- the game that is guaranteed to want all ten at once. A name is capped at
    -- twelve characters by the protocol and a row holds about thirty-two, so two
    -- names and their markers fit across with room to spare — where one name per
    -- row wasted two thirds of every line and then ran out anyway.
    local n = #S.players
    local i = 1
    -- Counted, not derived. `(i + 1) / 2` gives 1, 2, 3 on the console (integer
    -- division) and 1.0, 2.0, 3.0 in desktop Lua — where `"row" .. 1.0` is
    -- "row1.0", an element that does not exist. The conformance tests run this
    -- file in desktop Lua precisely so that class of divergence is caught, and
    -- the fix is not to divide.
    local line_no = 0
    while i <= n do
        local line = ""
        for col = 0, 1 do
            local p = S.players[i + col]
            if p then
                local mark = p.owner and "*" or (p.slot == S.mySlot and ">" or " ")
                line = line .. string.format("%s%-14s", mark,
                                             string.sub(tostring(p.name or "?"), 1, 12))
            end
        end
        line_no = line_no + 1
        row(line_no, line)
        i = i + 2
    end
    -- Row 7 leaves a gap under a full five rows of roster, so the count never
    -- looks like an eleventh player.
    row(7, string.format("  %d/10 PLAYERS   * HOST   > YOU", n))

    -- A ROOM WITH NOBODY IN IT IS A SYMPTOM, SO SAY SO.
    --
    -- The roster is retried every couple of seconds (SusTickLobby), but until an
    -- answer arrives this screen reads "0/10 PLAYERS / WAITING FOR THE HOST" —
    -- which is indistinguishable from a room that is genuinely empty and quiet,
    -- and gives a player nothing to act on. The CONNECTING view has said what is
    -- wrong after a few seconds for a long time; the room screen should too.
    if n == 0 and (S.emptyRoomWait or 0) >= ROSTER_PATIENCE then
        text("status", "NO ANSWER YET - O TO LEAVE")
        return
    end

    if S.isOwner then
        -- Say WHY start is refused rather than letting the button do nothing:
        -- the server rejects a round with fewer than four players.
        if n < 4 then
            text("status", string.format("NEED %d MORE PLAYER%s", 4 - n,
                                         (4 - n) == 1 and "" or "S"))
        else
            text("status", "READY WHEN YOU ARE")
        end
    else
        text("status", "WAITING FOR THE HOST")
    end
end

-- === chrome and prompts ==================================================

-- One plate: a slab behind the list.
--
-- The lobby was white text on black — a room browser that looked like a kernel
-- panic, and the first thing anybody says about it is that it feels empty. A
-- backing under the rows is what turns nine lines of text into a panel.
--
-- The prompt bar has NO plate. A bar across the bottom of the screen is a bar
-- whether or not it has anything to say; a glyph plus one word reads fine on
-- whatever is behind it.

local listPlate = nil

local function createChrome()
    if not P then return end
    -- Title through status: everything the lobby ever draws, in one slab,
    -- AUTHORED in the lobby canvas (make_scenes.py's build_lobby_chrome) rather
    -- than three sprites placed from a rect written here.
    listPlate = P.findPlate("lobby", "chrome")
    P.showPlate(listPlate, true)
end

--- What the pad does on the view currently up.
---
--- Three slots, so this is a choice about which three matter. On the room list
--- that is JOIN / HOST / REFRESH — joining is the point, hosting is the answer
--- when nothing is worth joining, and refreshing is the answer when the list is
--- stale. Paging, join-by-code and renaming are on the status line instead:
--- real, but not what anyone reaches for first.
local function drawPrompts()
    if not P then return end
    local B = P.BTN
    if S.view == VIEW.CONNECTING then
        P.setPrompts({ { B.SELECT, "DIAGNOSE" } })
    elseif S.view == VIEW.ROOMS then
        if #S.rooms == 0 then
            P.setPrompts({ { B.SQUARE, "HOST" }, { B.TRIANGLE, "REFRESH" },
                           { B.CIRCLE, "BACK" } })
        else
            P.setPrompts({ { B.CROSS, "JOIN" }, { B.SQUARE, "HOST" },
                           { B.TRIANGLE, "REFRESH" } })
        end
    elseif S.view == VIEW.CODE or S.view == VIEW.NAME then
        P.setPrompts({ { B.DPAD, "DIAL" }, { B.CROSS, "OK" }, { B.CIRCLE, "BACK" } })
    elseif S.view == VIEW.MAP then
        P.setPrompts({ { B.DPAD, "CHOOSE" }, { B.CROSS, "HOST" }, { B.CIRCLE, "BACK" } })
    elseif S.view == VIEW.IN_ROOM then
        -- START only for the owner, and only when the server would accept it.
        -- A prompt for a button that silently does nothing is how a player
        -- learns to stop reading the bar.
        -- PROMPT_SLOTS is 3 and setPrompts silently drops a fourth entry, so
        -- the owner's full bar is exactly full. Nothing else may be added here.
        if S.isOwner and #S.players >= 4 then
            P.setPrompts({ { B.START, "START" }, { B.SQUARE, "SHIP" },
                           { B.CIRCLE, "LEAVE" } })
        elseif S.isOwner then
            P.setPrompts({ { B.SQUARE, "SHIP" }, { B.CIRCLE, "LEAVE" } })
        else
            P.setPrompts({ { B.CIRCLE, "LEAVE" } })
        end
    else
        P.hidePrompts()
    end
end

-- Forward-declared so redraw() can call it without either becoming a global.
local drawCurrentView

local function redraw()
    -- Draw the view first so everything else is current, then stamp anything
    -- that outranks it over the status line.
    drawCurrentView()
    drawPrompts()
    if S.notice then
        text("status", S.notice)
        return
    end
    -- A link problem is worth saying on ANY screen. It replaces the status line
    -- rather than taking a row, because a row is a room somebody cannot see.
    local trouble = linkTrouble()
    if trouble then text("status", trouble) end
end

drawCurrentView = function()
    if S.view == VIEW.CONNECTING then
        drawConnecting()
    elseif S.view == VIEW.ROOMS then
        drawRoomList()
    elseif S.view == VIEW.CODE then
        drawCode()
    elseif S.view == VIEW.NAME then
        drawName()
    elseif S.view == VIEW.MAP then
        drawMapPick()
    elseif S.view == VIEW.IN_ROOM then
        drawRoomState()
    end
end

_G.SusRedraw = redraw

-- === server messages =====================================================

local function buildHandlers()
    local h = {}

    h[P.S2C.ROOM_LIST] = function(body)
        local page, pageCount, list = P.parseRoomList(body)
        -- THIS is what stops SusAnnounce retrying: the answer, not the question.
        S.announced = true
        S.rooms = list
        -- FIRST list means we are in: name yourself before doing anything else.
        --
        -- Not optional, and not a default everybody shares. This screen is the
        -- last moment before the room browser, and a lobby of players called the
        -- same thing is a vote screen nobody can use.
        if not S.namedYet then
            S.playerName = pickName(S.mySlot > 0 and S.mySlot or (#list + 1))
            SusBeginNameEdit()
            S.namedYet = true
            return
        end
        -- The server clamps the page it actually served, so trust its answer
        -- rather than what we asked for: paging past the end must not strand the
        -- cursor on a page that does not exist.
        S.page = page
        S.pageCount = pageCount > 0 and pageCount or 1
        -- No `math` on the console, so no math.max.
        if S.cursor > #S.rooms then
            S.cursor = #S.rooms > 0 and #S.rooms or 1
        end
        if S.view == VIEW.CONNECTING then S.view = VIEW.ROOMS end
        redraw()
    end

    h[P.S2C.ROOM_JOINED] = function(body)
        local roomId, yourSlot, code = P.parseRoomJoined(body)
        S.roomId = roomId
        S.mySlot = yourSlot
        S.joinCode = code
        -- DROP THE PREVIOUS ROOM'S ROSTER.
        --
        -- These used to survive a room change, and the roster retry latch is
        -- `#S.players == 0` — so a stale, non-empty list did not merely show the
        -- wrong names for a moment, it convinced the retry that nothing was
        -- owed. Lose the new ROOM_STATE and the console showed the OLD room's
        -- players permanently, with no request that would ever correct it.
        -- Reported as "names disappeared": they had not, they belonged to
        -- somewhere else.
        --
        -- `isOwner` goes with them, because a stale true offers a START prompt
        -- for a room this player does not own, which the server then ignores.
        S.players = {}
        S.isOwner = false
        -- Which ship this room is on. Taken from the room list where we have it
        -- (joining from the list), and otherwise left at what we asked for
        -- (hosting) — so the room screen names a map either way rather than
        -- always claiming the first one. GameStarting is authoritative later.
        for i = 1, #S.rooms do
            if S.rooms[i].id == roomId then S.roomMapId = S.rooms[i].mapId end
        end
        S.view = VIEW.IN_ROOM
        S.notice = nil
        redraw()
    end

    h[P.S2C.ROOM_REJECTED] = function(body)
        local reason = P.u8(body, 1)
        local why = "THAT DID NOT WORK"
        if reason == P.REJECT.FULL then why = "THAT ROOM IS FULL"
        elseif reason == P.REJECT.NOT_FOUND then why = "NO ROOM WITH THAT CODE"
        elseif reason == P.REJECT.IN_PROGRESS then why = "THAT GAME ALREADY STARTED"
        elseif reason == P.REJECT.SCENE_MISMATCH then why = "THEY ARE ON ANOTHER VERSION"
        elseif reason == P.REJECT.TOO_FEW_PLAYERS then why = "NEED 4 PLAYERS TO START"
        end
        -- Stay wherever they were; they may pick another room or fix the code.
        -- A refused START is answered in the room, not back at the room list.
        --
        -- VIEW.STARTING is a refusal that arrives AFTER the countdown began: the
        -- server re-checks the player count when it expires, because people leave
        -- during those five seconds, and a round that starts below the minimum is
        -- over before anyone moves. The console is still a MEMBER of the room, so
        -- the way out is back to the room, not back to the room list - dropping to
        -- VIEW.ROOMS showed a browser to somebody who had not left anything.
        if S.view == VIEW.STARTING then
            S.view = VIEW.IN_ROOM
            redraw()
        elseif S.view ~= VIEW.CODE and S.view ~= VIEW.IN_ROOM then
            S.view = VIEW.ROOMS
        end
        SusNotice(why)
    end

    h[P.S2C.ROOM_STATE] = function(body)
        local ownerSlot, list = P.parseRoomState(body)
        S.players = list
        S.isOwner = (ownerSlot == S.mySlot)
        -- The answer a returning console was waiting for. Latching here rather
        -- than on the send is the same rule ROOM_LIST follows: one dropped
        -- packet should cost a second, not leave the room permanently empty.
        if S.rejoining then
            S.rejoining = false
            S.announced = true
        end
        if S.view == VIEW.IN_ROOM then redraw() end
    end

    h[P.S2C.MAP_CHANGED] = function(body)
        -- The server is the only thing that decides this, including for the
        -- owner who asked: a console that painted its own choice before being
        -- told would show a different ship from everyone else the moment a
        -- request was refused for a reason it could not see.
        S.roomMapId = P.parseMapChanged(body)
        -- Also the answer for a console that joined BY CODE, which has no room
        -- list entry to read a map off and would otherwise name the wrong ship
        -- until the round started.
        if S.view == VIEW.IN_ROOM or S.view == VIEW.MAP then redraw() end
    end

    h[P.S2C.GAME_STARTING] = function(body)
        local mapId = P.parseGameStarting(body)
        S.roomMapId = mapId
        -- Remember it across the round. Scene.Load wipes the Lua state, so this
        -- is the only thing that survives to tell a returning console which ship
        -- its room is on — the server never says again, and the map cannot be
        -- worked out from the roster.
        if Persist and Persist.Set then Persist.Set("mapid", mapId) end
        S.view = VIEW.STARTING
        clearRows()
        text("title", P.mapName(mapId))
        row(6, "            GET READY")
        text("status", "")
        -- The handover. Persistence keeps the slot across the scene load;
        -- without it clearScene() drops the session and we rejoin as a brand-new
        -- player to a room now full of the players we were moving with.
        -- Order matters: SetPersistent BEFORE Load. See ROOM_PROTOCOL.md.
        Net.SetPersistent(true)
        -- The SERVER decides the map, not us: everybody in the room has to load
        -- the same scene or they end up on separate ships, and the only thing
        -- both ends agree on is what the server said.
        Scene.Load(P.gameScene(mapId))
    end

    return h
end

local function ready()
    if handlers then return true end
    P = PSXSUS
    if not P then
        Debug.Log("PSXSUS lobby: psxsus_protocol.lua is missing or attached AFTER lobby.lua")
        return false
    end
    if P.ROOMS_PER_PAGE ~= ROW_COUNT then
        Debug.Log("PSXSUS lobby: ROW_COUNT disagrees with the protocol's ROOMS_PER_PAGE")
    end
    handlers = buildHandlers()
    return true
end

-- === scene lifecycle =====================================================

function onSceneCreationStart()
    -- ARE WE COMING BACK FROM A ROUND, or in from the title screen?
    --
    -- Two completely different situations that reach this same function, and
    -- treating them alike is why "play again" used to dump the whole room on the
    -- NAME ENTRY screen: the lobby wiped its state, forgot it was in a room, and
    -- the first ROOM_LIST tripped the first-time naming gate below.
    --
    -- The engine already knows. `Net.SetPersistent(true)` is what the game scene
    -- sets before Scene.Load so the session — and therefore the slot, and
    -- therefore the room membership — survives the load; clearScene() takes the
    -- resetSceneBindings() path for a persistent session, which deliberately
    -- leaves that flag alone. The menu enters the lobby with it false. So the
    -- flag IS the answer, and no second copy of the fact has to be invented.
    local returning = Net.IsPersistent and Net.IsPersistent()

    S.cursor = 1
    S.joinCode = ""
    S.isOwner = false
    S.announceWait = 0
    S.rooms = {}
    S.page = 0
    S.pageCount = 1
    S.players = {}
    S.codeChars = { 1, 1, 1, 1 }
    S.codePos = 1
    S.notice = nil

    if returning then
        -- Still in the room, still named, still holding the slot. What is gone
        -- is the ROSTER, which went with the Lua state and which the server only
        -- broadcasts when it CHANGES — and coming back from a round changes
        -- nothing, the same people are in the same room. So it has to be asked
        -- for, exactly as the game scene asks on the way in.
        --
        -- The ROSTER request is not sent from here: SendData would return false
        -- until the handshake below completes, so it would be dropped.
        -- SusAnnounce owns the ask-and-retry, and `rejoining` is what tells it
        -- which question to ask.
        S.mySlot = Net.LocalSlot()
        S.roomId = 0            -- unknown until the server says; unused in-room
        S.namedYet = true       -- the server has had our name since we joined

        -- RE-HELLO. THIS IS NOT OPTIONAL AND IT IS NOT AUTOMATIC.
        --
        -- This line used to be absent, with a comment claiming the session
        -- "re-Hellos with c_flagRebind once the new scene is up" by itself. It
        -- does not. `NetworkManager::begin()` is reachable only from
        -- `Net.Connect()`; clearScene() takes the resetSceneBindings() path for a
        -- persistent session, which deliberately leaves the link state and the
        -- scene hash alone. So the console came back from a round still telling
        -- the server it was in the GAME scene, forever.
        --
        -- The server groups and gates on that hash. `Room.rebind` only adopts a
        -- new scene hash once EVERY member has reported it, and a member reports
        -- one only by Hello — so with no member ever sending one, the ROOM stayed
        -- pinned to the game scene too. `_h_list_rooms` filters rooms to those
        -- matching the asker's hash, so the room silently vanished from every
        -- room list, and `Room.add` answered SCENE_MISMATCH to anyone trying to
        -- join it — which this file renders as "THEY ARE ON ANOTHER VERSION"
        -- about a room that was perfectly fine.
        --
        -- That one missing call was: rooms only some players could see, rooms
        -- nobody could rejoin after a match, TRIANGLE listing nothing, and
        -- leaving a game to find the room you just left gone. The game scene has
        -- always done this unconditionally on its side of the same handover
        -- (scene_game.lua, onSceneCreationStart); this is the other half.
        --
        -- Safe on a persistent session: begin() sees the held slot and rebinds
        -- rather than re-joining, so the slot, the room membership and the name
        -- all survive. Read LocalSlot() BEFORE this, not after.
        Net.Connect()
        -- Which ship the room is on, stashed on the way OUT (see GAME_STARTING).
        -- Persist is numbers-only and this is a number, which is the one kind of
        -- thing it is good for. Without it the roster title comes back reading
        -- HULK for every room, because 0 is what a fresh S table starts on.
        S.roomMapId = (Persist and Persist.Get and Persist.Get("mapid")) or 0
        S.announced = false     -- there IS still something to ask for
        S.rejoining = true
        S.view = VIEW.IN_ROOM
    else
        S.mySlot = -1
        S.roomId = 0
        S.namedYet = false
        S.announced = false
        S.rejoining = false
        S.view = VIEW.CONNECTING
        -- The lobby is where a session BEGINS, so it is not persistent. A player
        -- who backs out must not carry a stale slot around.
        Net.SetPersistent(false)
        Net.Connect()
    end

    -- WHAT WE ARE CALLED IS A SEPARATE QUESTION FROM WHERE WE ARE.
    --
    -- `returning` answers "am I still in a room", and the two used to be
    -- answered together: anyone not still in a room was treated as nameless and
    -- shown the editor. That is why leaving a finished round landed you back on
    -- NAME ENTRY. You HAD left the room, so the first ROOM_LIST tripped the
    -- first-time naming gate -- even though you had been called something for
    -- the whole match, and everyone else had spent it reading that name.
    --
    -- Persist outlives the scene load, so the name is still here even when the
    -- room is not. Restoring it here makes the gate mean what it says: it fires
    -- when there is genuinely no name, not merely when there is no room.
    local remembered = recallName()
    if remembered then
        S.playerName = remembered
        S.namedYet = true
    end

    -- The lobby is a MENU. There is no avatar here, nothing at either end
    -- consumes a position update, and sending them is not free: measured on a
    -- real console, this scene was spending 894 B/s -- essentially the whole
    -- outbound budget -- broadcasting a player that did not exist, while the room
    -- roster it was sitting there waiting for queued behind that traffic.
    --
    -- The server already declined to replicate a lobby room (Game.replicates);
    -- this is the console's half of the same decision.
    if Net.SetReplicationEnabled then Net.SetReplicationEnabled(false) end
end

function onSceneCreationEnd()
    if not ready() then return end

    canvas = UI.FindCanvas("lobby")
    if canvas < 0 then
        Debug.Log("PSXSUS lobby: no canvas named 'lobby' in this scene")
        return
    end
    ui["title"] = UI.FindElement(canvas, "title")
    ui["status"] = UI.FindElement(canvas, "status")
    -- ROW_COUNT is the PACKET size (fifteen rooms in one reliable packet) and
    -- only VISIBLE_ROWS of them are authored, so the rest resolve to -1 — which
    -- `show`/`text` already tolerate. Looked up anyway rather than capped here,
    -- so that widening the scene needs no change on this side.
    for i = 1, ROW_COUNT do
        ui[rowName(i)] = UI.FindElement(canvas, rowName(i))
    end
    UI.SetCanvasVisible(canvas, true)

    -- Chrome first, prompt glyphs second: both are screen-pinned sprites on the
    -- same layer, and creation order settles ties within a layer.
    createChrome()
    P.initPrompts("lobby")

    -- Nothing is sent here. The handshake has not finished, so Net.SendData
    -- would return false and the room list would never arrive — the lobby would
    -- sit on "NO ROOMS" forever. SusAnnounce() below does it once we are up.

    -- COLD START ONLY: ask the memory card what we are called.
    --
    -- Persist has already answered if there was anything to answer with, so
    -- reaching this means the console was switched on since the last time it had
    -- a name -- the one moment where stopping for a card access is worth it.
    -- Coming back from a round never gets here, so a round trip through the game
    -- scene never pays for card I/O.
    --
    -- Placed after the canvas is built because a failure has something to say and
    -- SusNotice needs somewhere to say it.
    if not S.namedYet then
        local fromCard = loadNameFromCard()
        if fromCard then
            S.playerName = fromCard
            S.namedYet = true
            -- Straight into Persist as well, so the next scene load is answered
            -- from RAM and never touches the card again.
            rememberName(fromCard)
            SusNotice("LOADED " .. fromCard .. " FROM CARD")
        end
    end

    redraw()
end

--- Called from lobby_input.lua every frame once Net.IsConnected(). Sends our name
--- and asks for the room list, and KEEPS asking until a list comes back.
---
--- The latch is on the answer, not on the question. Latching on the send meant a
--- single lost ROOM_LIST left the lobby on "LOADING ROOMS..." permanently with
--- nothing that would ever ask again — and the reply is the largest message the
--- lobby exchanges, so it is the most likely one to be lost on a marginal link.
--- One dropped packet should cost a second, not the session.
--- Clocks that must run in EVERY view, including the ones that return early.
---
--- Called from lobby_input's onUpdate before the connected check, because the
--- screen this paces is the one you are on when you are NOT connected.
_G.SusTickLobby = function(dt)
    dt = dt or 0
    if S.view == VIEW.CONNECTING then
        S.connectWait = S.connectWait + dt
    else
        S.connectWait = 0
    end

    -- KEEP ASKING WHO IS IN THE ROOM until somebody answers.
    --
    -- ROOM_STATE is broadcast only when the roster CHANGES, and the copy sent on
    -- joining is a single reliable packet like any other — lose it and the
    -- console sits in a room it cannot see anyone in, for as long as nobody else
    -- joins or leaves. Playtesters hit exactly that: "player joins room
    -- successfully but other's usernames not showing".
    --
    -- Latched on the ANSWER (`#S.players > 0`), the same rule the room list and
    -- the rejoin path follow, because the link accepting a request says nothing
    -- about the reply arriving.
    if S.view == VIEW.IN_ROOM and #S.players == 0 then
        S.rosterWait = S.rosterWait - dt
        if S.rosterWait <= 0 then
            S.rosterWait = ANNOUNCE_RETRY
            if Net.IsConnected and Net.IsConnected() then
                Net.SendData(P.requestState())
            end
        end
        -- How long we have been looking at a room with nobody in it. Only used
        -- to say so on screen (see drawRoomState); the retry above is what
        -- actually fixes it.
        S.emptyRoomWait = (S.emptyRoomWait or 0) + dt
    else
        S.rosterWait = 0
        S.emptyRoomWait = 0
    end

    -- RECONNECT, RATHER THAN WAIT FOREVER, WHILE THE LINK IS DOWN.
    --
    -- Under PCSX-Redux the console announces itself to the PC by WRITING THE
    -- SIO1 CONTROL REGISTER: Redux only emits its flow-control message as a side
    -- effect of that write, and drops it silently if the SIO1 client is not
    -- connected yet. Sio1::init() performs those writes, and it runs in exactly
    -- one place — Net.Connect(). Redux resolves the console to polled RX, whose
    -- drain path only rewrites CTRL on a hardware serial error Redux never
    -- generates. So the control register is written three times at boot and
    -- never again.
    --
    -- The Hello retry does not help: it is a ~3Hz retry that only ever touches
    -- the DATA register. Start the emulator's SIO1 client after the console has
    -- booted and the console sits on CONNECTING with no way out — which is why
    -- playtesters had to disable and re-enable the client by hand to get in.
    --
    -- Calling Connect() again re-runs Sio1::init(), which is the only thing on
    -- this side that can produce a fresh announcement. Deliberately scoped to
    -- the CONNECTING view so it can never fire during a match.
    if S.view == VIEW.CONNECTING and not (Net.IsConnected and Net.IsConnected()) then
        S.reconnectWait = (S.reconnectWait or 0) - dt
        if S.reconnectWait <= 0 then
            S.reconnectWait = RECONNECT_RETRY
            Net.Connect()
        end
    else
        S.reconnectWait = RECONNECT_RETRY
    end
end

_G.SusAnnounce = function(dt)
    if S.announced then return end
    if not ready() then return end

    -- Count down before re-asking. Wall-clock, because the frame rate is not
    -- something this can assume: at 4fps a frame-counted retry would fire once
    -- every eight seconds.
    if S.announceWait > 0 then
        S.announceWait = S.announceWait - (dt or 0)
        if S.announceWait > 0 then return end
    end

    if S.rejoining then
        -- Back from a round: already in the room, already named, already holding
        -- the slot. Asking for the room BROWSER's list here would be asking the
        -- wrong question — the roster is the only thing missing. Latched on the
        -- answer (ROOM_STATE) like everything else in this file.
        --
        -- The NAME goes with it, which it did not used to. The server is told a
        -- name once, on the way in, and holds it against the session; a rejoin
        -- that lands on a session which no longer carries it -- a silence
        -- timeout, a console reset the bridge hid, a rebind onto a fresh record
        -- -- left this console in the room under no name at all, and this path
        -- had no way to put one back because it never sent one. It costs a
        -- 13-byte message to make that unfixable case fix itself.
        --
        -- Guarded on having a name rather than assumed: sending an empty one
        -- would blank us on a server that had it right all along.
        if S.playerName ~= "" and not Net.SendData(P.setName(S.playerName)) then
            S.announceWait = ANNOUNCE_BACKOFF
            return
        end
        if Net.SendData(P.requestState()) then
            S.announceWait = ANNOUNCE_RETRY
        else
            S.announceWait = ANNOUNCE_BACKOFF
        end
        return
    end

    -- Both or neither: sending the name without the request leaves the server
    -- holding a name for a console that never asked for anything.
    if Net.SendData(P.setName(S.playerName)) and Net.SendData(P.listRooms(0)) then
        S.announceWait = ANNOUNCE_RETRY
    else
        -- The reliable queue is full. Come back very soon rather than burning a
        -- whole retry interval on a transient.
        S.announceWait = ANNOUNCE_BACKOFF
    end
end

function onNetData(payload)
    if not ready() then return end
    local subtype, body = P.decode(payload)
    if not subtype then return end
    local h = handlers[subtype]
    if h then h(body) end
    -- Unknown subtypes are ignored, not fatal: a newer server may say things
    -- this build has never heard of, and the lobby should keep working.
end

-- === driven by lobby_input.lua ===========================================

--- Forget everything that belonged to the room we were just in.
---
--- Leaving a room is a state change on THIS console, not only a message to the
--- server, and it used to be neither: the CIRCLE handler sent LeaveRoom, flipped
--- the view to ROOMS and left every room-scoped field standing.
---
--- The damaging one was `rejoining`. A player who came back from a round and
--- then left had it stuck true, so SusAnnounce kept taking its rejoining branch
--- and asking REQUEST_STATE about a room it had already left — which the server
--- answers by doing nothing at all, because the session is roomless. `announced`
--- could therefore never latch, the room-list retry never resumed, and the
--- single listRooms fired at the moment of leaving became the only chance the
--- console would ever get. Lose that one reply and the browser stayed empty for
--- the rest of the session, with only manual TRIANGLE presses to save it.
_G.SusLeaveRoomState = function()
    S.rejoining = false
    S.announced = false     -- ask for the room list again, and keep asking
    S.mySlot = -1
    S.roomId = 0
    S.joinCode = ""
    S.players = {}
    S.isOwner = false
    S.rosterWait = 0
    S.emptyRoomWait = 0
end

_G.SusRoomCount = function() return #S.rooms end

_G.SusRoomIdAt = function(i)
    local r = S.rooms[i]
    return r and r.id or 0
end

--- The map of the room under the cursor, so joining from the list knows which
--- ship it is about to be on before the server confirms.
_G.SusRoomMapAt = function(i)
    local r = S.rooms[i]
    return r and r.mapId or 0
end
